import json
import re

with open('/home/ubuntu/.agent-ml-research-prod42/projects/clkc_mech_interp/logs/workers/worker_code_steering-script-107_20260522T081012.log', 'r') as f:
    lines = f.readlines()

for i, line in enumerate(lines):
    try:
        obj = json.loads(line.strip())
        if isinstance(obj, dict) and obj.get('type') == 'assistant':
            msg = obj.get('message', {})
            content = msg.get('content', [])
            if isinstance(content, list):
                for item in content:
                    if isinstance(item, dict) and item.get('name') == 'mcp__agent-ml-research__ssh_execute':
                        inp = item.get('input', {})
                        cmd = inp.get('command', '')
                        if 'en_conflict_test_verified' in cmd:
                            # Extract script between SCRIPT_EOF
                            match = re.search(r"<< 'SCRIPT_EOF'\n(.*)\nSCRIPT_EOF", cmd, re.DOTALL)
                            if match:
                                script = match.group(1)
                                # Find the test data loading section
                                script_lines = script.split('\n')
                                for j, sline in enumerate(script_lines):
                                    if 'Load test data' in sline or 'conflict_test_verified' in sline:
                                        start = max(0, j - 2)
                                        end = min(len(script_lines), j + 20)
                                        for k in range(start, end):
                                            print(f"{k:4d}: {script_lines[k]}")
                                        print("\n---\n")
    except:
        pass
